rowdata.pyStepsJavaSource:
sTargetEmbeddedPage = pega_rules_default.unquote(sTargetEmbeddedPage);
sPageProperty = pega_rules_default.unquote(sPageProperty);

String workPageForSplitForEach = "newWorkCover";
boolean fromSplitForEach = false;

if(sPageProperty.equals("") && tools.findPage("newWorkCover") != null &&  myStepPage.getIfPresent( "pxFlow" ) == null )
{
	fromSplitForEach = true;
	String workPageName = tools.getParamValue("ReferencePageName");
	if(!workPageName.equals(""))
	{
		workPageForSplitForEach = workPageName;
	}	
}

boolean hasDataTransform = false;
if ((!tools.getParamValue("DataTransform").equals(""))) {
	hasDataTransform = true;
}

String sClassName = sPageClass;

// Validate the TargetEmbeddedPageProperty if ChildClass is defined
if (sMapType.equals("COPYTOPAGE") && !sPageClass.equals("")) {
	if (sTargetEmbeddedPage.equals("")) {
		myStepPage.addMessage("TargetPagePropertyRequired", "pyMessageLabel", "@baseclass");
		return true;
	} else if (!tools.getDictionary().validateReference(sPageClass,sTargetEmbeddedPage)) {
		myStepPage.addMessage("InvalidPropertyForClass\t" + sTargetEmbeddedPage + "\t" + sPageClass, "pyMessageLabel", "@baseclass");
		return true;
	}
}


if (!sClassName.equals("")) {

	ClipboardPage parentRef = myStepPage.getTopLevelPage();
	if(fromSplitForEach)
			parentRef = tools.findPage(workPageForSplitForEach);

	if (!pega_processengine_flowutilities.pzIsACoveredClass(tools,parentRef,sClassName)) {
		parentRef.addMessage("ClassIsNotCovered\t" + sPageClass, "pyMessageLabel", "@baseclass");
		return true;
	}

}


// Set up pages to call the activities
HashStringMap params = new HashStringMap();
HashStringMap params1 = new HashStringMap();
params.putString("pxObjClass", "Rule-Obj-Activity");


params.putString("pyClassName", myStepPage.getTopLevelPage().getClassName());

if(sPageProperty.equals("")) { // called from split-for-each
	if(!sClassName.equals(""))
		params.putString("pyClassName", sClassName);
}

params.putString("pyActivityName", "CreateWorkPage");

params1.putString("pxObjClass", "Rule-Obj-Activity");
//params1.putString("pyClassName", myStepPage.getTopLevelPage().getClassName());
params1.putString("pyActivityName", "AddCoveredWork");


String whenRule = tools.getParamValue("WhenRule");
ClipboardProperty cpPageProp = null;

char propMode = '\0';
if (!sPageProperty.equals("")) {
	cpPageProp = myStepPage.getProperty(tools.getParamValue("PageProperty"));
	propMode = cpPageProp.getMode();
}

// If it is a pagelist or page group, start the iteration 

boolean childClasSpecified = true;

if (propMode == ImmutablePropertyInfo.MODE_PAGE_LIST || propMode == ImmutablePropertyInfo.MODE_PAGE_GROUP) {

	Iterator iter = cpPageProp.iterator();
	int i = 0;
	while(iter.hasNext()) {
		ClipboardProperty cpResult = (ClipboardProperty) iter.next();
		ClipboardPage pgSource = cpResult.getPageValue();
		if(!"".equals(whenRule) && !pega_rules_utilities.callWhen(tools,whenRule,pgSource)){											
			continue;					
		}

			ParameterPage newParamsPage = new ParameterPage();
			if (sPageClass.equals("")) {
                childClasSpecified = false;
			}

			if(!childClasSpecified)
				sPageClass = pgSource.getClassName();

			i++;
			// Some error checking
			if (sClassName.equals("")) {
				// Check that source class is covered by parent class
				if (!pega_processengine_flowutilities.pzIsACoveredClass(tools,myStepPage,sPageClass)) {
					myStepPage.addMessage("ClassIsNotCovered\t" + sPageClass, "pyMessageLabel", "@baseclass");
					break;
				}
				if (sMapType.equals("COPYTOPAGE")) {
					// Check that sTargetEmbeddedPage is a valid property in the child class
					if (!tools.getDictionary().validateReference(sPageClass,sTargetEmbeddedPage)) {
						myStepPage.addMessage("InvalidPropertyForClass\t" + sTargetEmbeddedPage + "\t" + sPageClass, "pyMessageLabel", "@baseclass");
						break;
					}
				}
			}
			if (sMapType.equalsIgnoreCase("COPYTOCHILD") && !hasDataTransform) {
				// Check that the child's class is equal to or derives from the source page property class
				String sListClass = pgSource.getClassName();

                    if(childClasSpecified){
						if (!(sListClass.equals(sPageClass) || pega_rules_default.isAncestorOf(tools,sPageClass,sListClass))) {
							myStepPage.addMessage("DescendantClassRequired", "pyMessageLabel", "@baseclass");
							break;
						}
                    }
			}		


			String sPageCleanClass = pega_processarchitect_pzprocessarchitect.pzPageNameClean(sPageClass+"_"+pega_rules_datetime.CurrentDateTime());
			String workPageName = "IteratePage_"+ sPageCleanClass + String.valueOf(i);
			newParamsPage.putString("InsClass",sPageClass);
			newParamsPage.putString("workPage",workPageName);
			newParamsPage.putString("keepCoverPageName", "true");
			newParamsPage.putString("FlowType",sFlowName);
			newParamsPage.putString("OnlyCreateOutputPageIfError", "true");
			newParamsPage.putString("CoverClass", myStepPage.getClassName());
			newParamsPage.putString("callAddCoveredDefaults", "true");
			newParamsPage.putString("CoverPage", myStepPage.getName());

			// Call CreateWorkPage
			tools.doActivity(params, myStepPage, newParamsPage);
			//myStepPage.getProperty("pzInsKey").toString();
			// Copy page if sMapType is COPYTOPAGE
			ClipboardPage wp = tools.findPage(workPageName);
			String errMessage = "";
			if (wp != null) {
				if (sMapType.equals("COPYTOPAGE")) {
					ClipboardProperty trProp = wp.getProperty(sTargetEmbeddedPage);
					trProp.setValue(cpResult);
					tools.getDictionary().validate(trProp);
				} else if (sMapType.equalsIgnoreCase("COPYTOCHILD") && !hasDataTransform) {
					wp.putAll(pgSource, ClipboardPage.PUTALL_KEEPNEW);
					tools.getDictionary().validate(wp, false);
				}
				else if (hasDataTransform) {
					ParameterPage mParams = new ParameterPage();
					if (!tools.getParamValue("SourcePageParamName").equals("")) {
						mParams.putString(tools.getParamValue("SourcePageParamName"), pgSource.getReference());
					}
                  	mParams.putString("ParentPageParamName", tools.findPage(tools.getParamValue("PrimaryPage")).getReference());
					tools.applyModel(wp, mParams, tools.getParamValue("DataTransform"));
				}

				if (!wp.hasMessages()) {

					//  call pyAddChildWorkDefaults activity
					HashStringMap extnAct = new HashStringMap();
					extnAct.putString("pxObjClass", "Rule-Obj-Activity");
					extnAct.putString("pyClassName", myStepPage.getClassName());
					extnAct.putString("pyActivityName", "pyAddChildWorkDefaults");

					ParameterPage paramsPageExtn = new ParameterPage();
					paramsPageExtn.putString("ChildPage",workPageName);

					tools.doActivity(extnAct, pgSource, paramsPageExtn);
					// end call pyAddChildWorkDefaults activity

					params1.putString("pyClassName", wp.getClassName());
					// Call AddCoveredWork
					tools.doActivity(params1, wp, newParamsPage);
				}
				if (wp.hasMessages()) {
					myStepPage.addMessage(wp.getMessagesAll());
				}
				wp.removeFromClipboard();
			}
			if (myStepPage.hasMessages()) {
				break;
			}				
		}
} else if (propMode == '\0' || propMode == ImmutablePropertyInfo.MODE_PAGE ) {

	// if a Page, create 1 child
	ParameterPage newParamsPage = new ParameterPage();
	ClipboardPage pgSource = myStepPage;
	if (propMode != '\0') {
		pgSource = cpPageProp.getPageValue();
	}


	if(!"".equals(whenRule) && !pega_rules_utilities.callWhen(tools,whenRule,pgSource))
	{
	}
	else
	{
		if (sPageClass.equals("")) {
			sPageClass = pgSource.getClassName();
		}
		// Some error checking
		if (sClassName.equals("")) {
			// Check that source class is covered by parent class
			if (!pega_processengine_flowutilities.pzIsACoveredClass(tools,myStepPage,sPageClass)) {
				myStepPage.addMessage("ClassIsNotCovered\t" + sPageClass, "pyMessageLabel", "@baseclass");
				return true;
			}
			if (sMapType.equals("COPYTOPAGE")) {
				// Check that sTargetEmbeddedPage is a valid property in the child class
				if (!tools.getDictionary().validateReference(sPageClass,sTargetEmbeddedPage)) {
					myStepPage.addMessage("InvalidPropertyForClass\t" + sTargetEmbeddedPage + "\t" + sPageClass, "pyMessageLabel", "@baseclass");
					return true;
				}
			}
		}
		if (sMapType.equalsIgnoreCase("COPYTOCHILD") && !hasDataTransform) {
			// Check that the child's class is equal to or derives from the source page property class
			String sListClass = pgSource.getClassName();
			if (!(sListClass.equals(sPageClass) || pega_rules_default.isAncestorOf(tools,sPageClass,sListClass))) {
				if(fromSplitForEach)
					myStepPage = tools.findPage(workPageForSplitForEach);
				myStepPage.addMessage("DescendantClassRequired", "pyMessageLabel", "@baseclass");
				return true;
			}
		}

		ClipboardPage parentPage  = myStepPage.getTopLevelPage();

		if(fromSplitForEach) // When no pageproperty, that means this is called from a split-for-each, so pyWorkPage becomes the parent page
			parentPage = tools.findPage(workPageForSplitForEach);

		String sPageCleanChildClass = pega_processarchitect_pzprocessarchitect.pzPageNameClean(sPageClass+"_"+pega_rules_datetime.CurrentDateTime());
		String workPageName = "IteratePage_"+ sPageCleanChildClass;
		newParamsPage.putString("InsClass",sPageClass);
		newParamsPage.putString("workPage", workPageName);
		newParamsPage.putString("keepCoverPageName", "true");
		newParamsPage.putString("FlowType",sFlowName);
		newParamsPage.putString("OnlyCreateOutputPageIfError", "true");
		newParamsPage.putString("CoverClass", parentPage.getClassName());
		newParamsPage.putString("callAddCoveredDefaults", "true");
		newParamsPage.putString("CoverPage", parentPage.getName());
		tools.doActivity(params, myStepPage, newParamsPage);

		ClipboardPage wp = tools.findPage(workPageName);
		String errMessage = "";
		if (wp != null) {
			if (sMapType.equals("COPYTOPAGE")) {
				ClipboardProperty trProp = wp.getProperty(sTargetEmbeddedPage);
				if (!cpPageProp.equals("")) {
					trProp.setValue(cpPageProp);
				}
				else {
					trProp.setValue(myStepPage);
				}
				tools.getDictionary().validate(trProp);
			} else if (sMapType.equalsIgnoreCase("COPYTOCHILD") && !hasDataTransform) {
				wp.putAll(pgSource, ClipboardPage.PUTALL_KEEPNEW);
				tools.getDictionary().validate(wp, false);
			} else if (hasDataTransform) {

				ParameterPage mParams = new ParameterPage();
				if(!tools.getParamValue("SourcePageParamName").equals("")) {
					mParams.putString(tools.getParamValue("SourcePageParamName"), pgSource.getReference());
				}
              	mParams.putString("ParentPageParamName", tools.findPage(tools.getParamValue("PrimaryPage")).getReference());
				tools.applyModel(wp, mParams, tools.getParamValue("DataTransform"));
			}
			if (!wp.hasMessages()) {

				//  call pyAddChildWorkDefaults activity
				HashStringMap extnAct = new HashStringMap();
				extnAct.putString("pxObjClass", "Rule-Obj-Activity");
				extnAct.putString("pyClassName", myStepPage.getClassName());
				extnAct.putString("pyActivityName", "pyAddChildWorkDefaults");

				ParameterPage paramsPageExtn = new ParameterPage();
				paramsPageExtn.putString("ChildPage",workPageName);

				tools.doActivity(extnAct, pgSource, paramsPageExtn);
				// end call pyAddChildWorkDefaults activity

				params1.putString("pyClassName", wp.getClassName());
				tools.doActivity(params1, wp, newParamsPage);
                sInsKey = wp.getProperty("pzInsKey").toString();
			}
			if (wp.hasMessages()) {

				if(fromSplitForEach)
					myStepPage = tools.findPage(workPageForSplitForEach);

				myStepPage.addMessage(wp.getMessagesAll());

			}
			wp.removeFromClipboard();
		}
	}	
} else {
	// Set message if not a page, pagelist or page group
	myStepPage.addMessage("PagePropertyRequired\t" + sPageProperty, "pyMessageLabel", "@baseclass");
}

